CREATE TABLE stredni_skoly (
    redizo VARCHAR(20) PRIMARY KEY,
    nazev VARCHAR(255),
    kod_zsj VARCHAR(20),
    adresa VARCHAR(255),
    lat DECIMAL(10, 6),
    lon DECIMAL(10, 6),
    web VARCHAR(255)
);

